"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["39043"],{54505(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_com_preliminar_sem_definitivo","status":422,"titulo":"A etapa publica resultado preliminar sem o definitivo do mesmo tipo de ato"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_com_preliminar_sem_definitivo","requisitos":["UNI-REQ-0157"],"oQueAconteceu":["Uma etapa do processo publica o resultado **preliminar** de um tipo de ato e n\xe3o publica o\\nresultado **definitivo** do mesmo tipo. O preliminar abre um ciclo de recurso, e sem o\\ndefinitivo a mat\xe9ria fica aberta, sem desfecho previsto para o candidato.","Como na [fase do cronograma](/erros/uniplus.selecao.processo_seletivo.fase_com_preliminar_sem_definitivo),\\nn\xe3o existe outra fase que conclua o ciclo: ele fecha dentro da pr\xf3pria etapa. Por isso o definitivo precisa estar nos produtos da pr\xf3pria etapa, com o\\nmesmo tipo de ato do preliminar. Um definitivo de outro tipo n\xe3o fecha o ciclo, porque a\\nmat\xe9ria \xe9 o tipo de ato. A mensagem de detalhe nomeia a etapa e o tipo de ato."],"comoResolver":["Acrescente aos produtos da etapa o resultado definitivo do mesmo tipo de ato do preliminar,\\ncom papel definitivo. Se o edital n\xe3o quer ciclo de recurso para aquela mat\xe9ria na etapa, retire o\\nresultado preliminar. O painel de conformidade mostra esta pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_conclusao_do_ciclo_recursal`."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);